import {
  type JsonSchema,
  type TypeContext,
  array,
  createTypeContext,
  declare,
  declareDefs,
  docComment,
  object,
  schemaType,
  typeDeclaration,
} from "./render-defs.js";

const expressionRef = "#/$defs/expression";
const nodesItemsRef = "#/properties/nodes/items";
const header = `// Generated by tooling/generate-types from definitions/composition.schema.json.
// Do not edit by hand.

`;

/** The types in \`src/values.ts\`, which generated types import. */
const valueTypes = [
  "Color",
  "ExpressionString",
  "ExpressionValue",
  "HexColor",
  "Vec2",
  "Vec3",
] as const;

interface PortSchema {
  readonly name: string;
  readonly kind: string;
  readonly variadic: boolean;
}

interface NodeVariant {
  readonly kind: string;
  readonly description: string;
  readonly category: string;
  readonly inputs: readonly PortSchema[];
  readonly outputs: readonly PortSchema[];
  readonly params: JsonSchema;
  readonly paramKinds: readonly (readonly [id: string, kind: string, schema: JsonSchema])[];
}

const quote = (value: string): string => JSON.stringify(value);

const union = (values: readonly string[]): string =>
  values.length === 0 ? "never" : values.map(quote).join(" | ");

const uniqueSorted = (values: readonly string[]): string[] => [...new Set(values)].sort();

const pascalCase = (value: string): string =>
  value
    .split(/[^a-zA-Z0-9]+/u)
    .filter(Boolean)
    .map((part) => `${part[0]?.toUpperCase() ?? ""}${part.slice(1)}`)
    .join("");

const typeNameForNode = (kind: string): string => `${pascalCase(kind)}Node`;

/** A param named after its node, such as the text node's `text_transform`, is not prefixed twice. */
const enumAliasForParam = (nodeKind: string, paramId: string): string => {
  const kind = pascalCase(nodeKind);
  const id = pascalCase(paramId);
  return id.startsWith(kind) ? id : `${kind}${id}`;
};

const requireString = (value: unknown, what: string): string => {
  if (typeof value !== "string") throw new Error(`${what} must be a string`);
  return value;
};

const portSchemas = (value: unknown, what: string): PortSchema[] =>
  array(value).map((port) => ({
    name: requireString(object(port).name, `${what} name`),
    kind: requireString(object(port).kind, `${what} kind`),
    variadic: object(port).variadic === true,
  }));

function nodeVariants(schema: JsonSchema): NodeVariant[] {
  const variants = array(object(object(object(schema.properties).nodes).items).oneOf);
  return variants.map((value) => {
    const variant = object(value);
    const properties = object(variant.properties);
    const kind = requireString(object(properties.type).const, "a node's `type.const`");
    const params = object(properties.params);
    return {
      kind,
      description: requireString(variant.description, `${kind} \`description\``),
      category: requireString(variant["x-lumen-category"], `${kind} \`x-lumen-category\``),
      inputs: portSchemas(variant["x-lumen-inputs"], `${kind} input`),
      outputs: portSchemas(variant["x-lumen-outputs"], `${kind} output`),
      params,
      paramKinds: Object.entries(object(params.properties)).map(([id, param]) => [
        id,
        requireString(object(param)["x-lumen-kind"], `${kind}.${id} \`x-lumen-kind\``),
        object(param),
      ]),
    };
  });
}

/** The literal half of an expression-capable param's `anyOf`, or the param itself. */
const withoutExpression = (param: JsonSchema): JsonSchema => {
  const branches = array(param.anyOf);
  const isExpression = (branch: unknown): boolean => object(branch).$ref === expressionRef;
  return branches.some(isExpression) ? object(branches.find((b) => !isExpression(b))) : param;
};

/** Declares the `${Node}${Param}` alias of each enum param whose type has another name. */
function declareEnumAliases(node: NodeVariant, context: TypeContext): void {
  for (const [id, kind, param] of node.paramKinds) {
    if (kind !== "enum") continue;
    const name = requireString(
      withoutExpression(param)["x-lumen-type"],
      `${node.kind}.${id} enum \`x-lumen-type\``,
    );
    const alias = enumAliasForParam(node.kind, id);
    if (alias !== name) declare(context, alias, `export type ${alias} = ${name};`);
  }
}

const renderNodeInterface = (node: NodeVariant, context: TypeContext): string =>
  `${docComment(node.description, "")}export interface ${typeNameForNode(node.kind)} extends CompositionNodeBase<${quote(
    node.kind,
  )}> {
  readonly params?: ${schemaType(node.params, context, "  ")};
}`;

const renderNodeMapMember = (node: NodeVariant): string =>
  `  readonly ${quote(node.kind)}: ${typeNameForNode(node.kind)};`;

const renderNodeInputMapMember = (node: NodeVariant): string =>
  `  readonly ${quote(node.kind)}: Omit<${typeNameForNode(node.kind)}, "id"> & {
    readonly id?: number;
  };`;

const renderNodeInputPortMapMember = (node: NodeVariant): string =>
  `  readonly ${quote(node.kind)}: ${union(uniqueSorted(node.inputs.map((port) => port.name)))};`;

const renderNodeVariadicPortMapMember = (node: NodeVariant): string =>
  `  readonly ${quote(node.kind)}: ${union(uniqueSorted(node.inputs.filter((port) => port.variadic).map((port) => port.name)))};`;

const renderNodeOutputKindMapMember = (node: NodeVariant): string =>
  `  readonly ${quote(node.kind)}: ${union(uniqueSorted(node.outputs.map((port) => port.kind)))};`;

const renderNodeInputPortKindMapMember = (node: NodeVariant): string => {
  const ports = node.inputs.map((port) => `readonly ${quote(port.name)}: ${quote(port.kind)}`);
  return `  readonly ${quote(node.kind)}: ${ports.length === 0 ? "{}" : `{ ${ports.join("; ")} }`};`;
};

const renderNodeInputPortTableMember = (node: NodeVariant): string => {
  const ports = node.inputs.map(
    (port) => `${quote(port.name)}: { kind: ${quote(port.kind)}, variadic: ${port.variadic} }`,
  );
  return `${docComment(node.description, "  ")}  ${quote(node.kind)}: ${ports.length === 0 ? "{}" : `{ ${ports.join(", ")} }`},`;
};

/** `nodes` tells a node's params from its input ports by name, so no kind may share one. */
function assertDistinctParamAndPortNames(node: NodeVariant): void {
  const ports = new Set(node.inputs.map((port) => port.name));
  const shared = node.paramKinds.map(([id]) => id).filter((id) => ports.has(id));
  if (shared.length > 0) {
    throw new Error(
      `\`${node.kind}\` has a param and an input port named ${shared.map((id) => `\`${id}\``).join(", ")}`,
    );
  }
}

const renderConst = (name: string, value: unknown): string =>
  `export const ${name} = ${JSON.stringify(value, null, 2)} as const;`;

function renderExpressionTables(schema: JsonSchema): string {
  const expressions = object(schema["x-lumen-expressions"]);
  const tables = {
    builtins: array(expressions.builtins),
    easings: array(expressions.easings),
    forms: array(expressions.forms),
    globals: array(expressions.globals),
    reserved: array(expressions.reserved),
  };
  return `${renderConst("expressionBuiltins", tables.builtins)}
export type ExpressionBuiltinName = (typeof expressionBuiltins)[number]["name"];

${renderConst("easingNames", tables.easings)}
/** Easing names accepted by \`tween\`. */
export type EasingName = (typeof easingNames)[number];

${renderConst("expressionGlobals", tables.globals)}
export type ExpressionGlobalName = (typeof expressionGlobals)[number]["name"];

/** Calls the expression parser handles itself, such as \`if\` and \`node\`, listed for documentation. */
${renderConst("expressionForms", tables.forms)}

/** Names that composition functions and their parameters may not take. */
${renderConst("expressionReservedNames", tables.reserved)}`;
}

const importValueTypes = (used: ReadonlySet<string>): string => {
  const names = valueTypes.filter((name) => used.has(name));
  return names.length === 0 ? "" : `import type { ${names.join(", ")} } from "../values.js";\n`;
};

/** The node and `$defs` types, the node tables, and what the root needs to import from them. */
function renderMetaTypes(schema: JsonSchema, context: TypeContext): string {
  const nodes = nodeVariants(schema);
  for (const node of nodes) assertDistinctParamAndPortNames(node);
  declareDefs(context, object(schema.$defs) as Record<string, JsonSchema>);
  const nodeInterfaces = nodes.map((node) => renderNodeInterface(node, context)).join("\n\n");
  for (const node of nodes) declareEnumAliases(node, context);

  const categories = uniqueSorted(nodes.map((node) => node.category));
  const portKinds = uniqueSorted(
    array(schema["x-lumen-portKinds"]).map((kind) => requireString(kind, "a port kind")),
  );
  const paramKinds = uniqueSorted(nodes.flatMap((node) => node.paramKinds.map(([, kind]) => kind)));
  const namedTypes = [...context.declarations.entries()]
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([, declaration]) => declaration)
    .join("\n");

  return `${header}${importValueTypes(context.used)}
export type NodeCategory = ${union(categories)};
export type NodePortKind = ${union(portKinds)};
export type NodeParamKind = ${union(paramKinds)};
export type NodeKind = ${union(uniqueSorted(nodes.map((node) => node.kind)))};

export const schemaVersion = ${JSON.stringify(schema["x-lumen-schemaVersion"])} as const;

/** The Lumen major.minor compositions are written for; an engine reads only its own. */
export const lumenSchemaVersion = ${JSON.stringify(schema["x-lumen-lumenSchemaVersion"])} as const;

${renderExpressionTables(schema)}

${namedTypes}

export interface CompositionNodeBase<TKind extends NodeKind> {
  readonly id: number;
  readonly type: TKind;
}

${nodeInterfaces}

export interface CompositionNodeByKind {
${nodes.map(renderNodeMapMember).join("\n")}
}

export interface CompositionNodeInputByKind {
${nodes.map(renderNodeInputMapMember).join("\n")}
}

export interface NodeInputPortNameByKind {
${nodes.map(renderNodeInputPortMapMember).join("\n")}
}

export interface NodeVariadicInputPortNameByKind {
${nodes.map(renderNodeVariadicPortMapMember).join("\n")}
}

export interface NodeOutputKindByKind {
${nodes.map(renderNodeOutputKindMapMember).join("\n")}
}

export interface NodeInputPortKindByKind {
${nodes.map(renderNodeInputPortKindMapMember).join("\n")}
}

export type CompositionNode<TKind extends NodeKind = NodeKind> = CompositionNodeByKind[TKind];
export type CompositionNodeInput<TKind extends NodeKind = NodeKind> = CompositionNodeInputByKind[TKind];
/** The input port names of a node kind, which a connection's \`to_port\` names. */
export type NodeInputPortName<TKind extends NodeKind = NodeKind> = NodeInputPortNameByKind[TKind];
/** The input ports of a node kind that take any number of connections. */
export type NodeVariadicInputPortName<TKind extends NodeKind = NodeKind> = NodeVariadicInputPortNameByKind[TKind];
/** What a node kind outputs, which the inputs it is connected to must take. */
export type NodeOutputKind<TKind extends NodeKind = NodeKind> = NodeOutputKindByKind[TKind];
/** What input \`TPort\` of a node kind takes; for a union of kinds, what any of them takes there. */
export type NodeInputPortKind<
  TKind extends NodeKind = NodeKind,
  TPort extends NodeInputPortName<TKind> = NodeInputPortName<TKind>,
> = TKind extends NodeKind
  ? TPort extends keyof NodeInputPortKindByKind[TKind]
    ? NodeInputPortKindByKind[TKind][TPort]
    : never
  : never;

/**
 * A name a node kind gives both a param and an input port: \`never\`, since \`nodes\` tells a node's
 * params from its inputs by name. \`nodeInputPorts\` fails to compile otherwise.
 */
export type NodeParamPortNameClash = {
  readonly [TKind in NodeKind]: Extract<
    keyof NonNullable<CompositionNodeByKind[TKind]["params"]>,
    NodeInputPortName<TKind>
  >;
}[NodeKind];

type NodeInputPortTable = {
  readonly [TKind in NodeKind]: {
    readonly [TPort in NodeInputPortName<TKind>]: {
      readonly kind: NodeInputPortKind<TKind, TPort>;
      readonly variadic: TPort extends NodeVariadicInputPortName<TKind> ? true : false;
    };
  };
};

/**
 * The input ports of each node kind by name, in the schema's order: what each takes, and whether
 * it takes a list of nodes.
 */
export const nodeInputPorts = {
${nodes.map(renderNodeInputPortTableMember).join("\n")}
} as const satisfies [NodeParamPortNameClash] extends [never]
  ? NodeInputPortTable
  : \`a param and an input port share the name \${NodeParamPortNameClash}\`;
`;
}

/** `LumenComposition`, with the node union standing in for the schema's inline `nodes` items. */
function renderRootType(schema: JsonSchema, context: TypeContext): string {
  const properties = object(schema.properties);
  const root = {
    ...schema,
    properties: {
      ...properties,
      nodes: { ...object(properties.nodes), items: { $ref: nodesItemsRef } },
    },
  };
  const rootContext: TypeContext = { ...context, used: new Set() };
  const declaration = typeDeclaration("LumenComposition", root, rootContext, true);
  const metaNames = [...rootContext.used].filter(
    (name) => name === "CompositionNode" || context.declarations.has(name),
  );
  return `${header}${importValueTypes(rootContext.used)}import type { ${metaNames.sort().join(", ")} } from "./meta.js";

${declaration}
`;
}

/** The contents of `generated/meta.ts` and `generated/schema.ts`. */
export function renderTypes(schema: JsonSchema): { readonly meta: string; readonly root: string } {
  const defs = object(schema.$defs) as Record<string, JsonSchema>;
  const context = createTypeContext(defs, [[nodesItemsRef, "CompositionNode"]]);
  const meta = renderMetaTypes(schema, context);
  return { meta, root: renderRootType(schema, context) };
}
